INSERT INTO `blogs` VALUES (0,'2024-08-05 15:28:12.883455',1,'2024-08-05 15:28:12.883455',1,'admin','<p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Không phải ngẫu nhiên mà Đà Lạt là điểm đến được mọi cặp đôi yêu thích. Nơi đây không chỉ nổi tiếng với các cảnh đẹp nên thơ như: Thác Datanla, núi Langbiang, vườn thú Zoodoo, vườn ánh sáng Lumiere, vườn cổ tích Tulu Tula, đồi Robin, Hồ Tuyền Lâm, món ăn hấp dẫn như: bánh ướt lòng gà, bánh căn, bánh tráng nướng,... mà cái tiết trời mát mẻ, dễ chịu cùng không khí trong lành, quang đãng cũng là lý do giúp Đà Lạt gây thương nhớ bao du khách. Đầu năm chưa biết đi đâu thì có thể tham khảo qua địa điểm&nbsp;<a href=\"https://travel.com.vn/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 51, 51);\">du lịch</a>&nbsp;Tết âm là Đà Lạt mộng mơ này bạn nhé!</p><p class=\"ql-align-justify\"><a href=\"https://media.vietravel.com/images/NewsPicture/du-xuan-ngay-tet-4.jpg\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 51, 51);\"><img src=\"https://media.vietravel.com/images/NewsPicture/du-xuan-ngay-tet-4.jpg\"><img src=\"https://www.vietravel.com/content/img/icon_zoom.png\" alt=\"Slideshow\"></a></p><p class=\"ql-align-center\"><a href=\"https://travel.com.vn/du-lich-da-lat.aspx\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 51, 51);\">Đà Lạt</a>&nbsp;là điểm dừng chân quen thuộc của nhiều cặp đôi</p><p class=\"ql-align-center\">&nbsp;</p><p><br></p>','da lat','Lâm Đồng','https://res.cloudinary.com/dbammk7wt/image/upload/v1722846491/fvdunad5fmxan3mks2ra.webp','DA LAT'),(0,'2024-08-05 16:19:11.817544',2,'2024-08-05 16:19:11.817544',1,'admin','<p class=\"ql-align-justify\">Không quá ồn ào, sôi động như Sài Gòn, Hà Nội mang trong mình vẻ đẹp nhẹ nhàng và bình yên cũng sẽ là một trong những điểm&nbsp;<a href=\"https://travel.com.vn/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 51, 51);\">du lịch</a>&nbsp;Tết âm tuyệt vời dành cho các cặp đôi. Ghé thăm thủ đô nghìn năm văn hiến này, bạn có thể dành thời gian dạo quanh phố cổ, hồ Hoàn Kiếm, thăm lăng Chủ tịch Hồ Chí Minh, Văn Miếu - Quốc Tử Giám,...</p><p class=\"ql-align-justify\"><a href=\"https://media.vietravel.com/images/NewsPicture/du-xuan-ngay-tet-8.jpg\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 51, 51);\"><img src=\"https://media.vietravel.com/images/NewsPicture/du-xuan-ngay-tet-8.jpg\"><img src=\"https://www.vietravel.com/content/img/icon_zoom.png\" alt=\"Slideshow\"></a></p><p class=\"ql-align-center\">Hà Nội nghìn năm văn hiến làm nao lòng bao du khách với vẻ đẹp nhẹ nhàng, yên bình</p><p class=\"ql-align-justify\"><br></p><p><br></p>','Ha Noi','Hà Nội','https://res.cloudinary.com/dbammk7wt/image/upload/v1722849550/evfmjyamv5mrf8s1frz8.webp','Ha Noi'),(0,'2024-08-05 16:20:42.329809',3,'2024-08-05 16:20:42.329809',1,'admin','<p class=\"ql-align-justify\">Thành phố&nbsp;<a href=\"https://travel.com.vn/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 51, 51);\">du lịch</a>&nbsp;Đà Nẵng sở hữu nhiều khách sạn từ 3 sao, 4 sao, 5 sao cho bạn và người ấy dễ dàng lựa chọn. Có thể kể đến một vài cái tên nổi bật cả về chất lượng, giá cả, vị trí, cơ sở vật chất, dịch vụ như: Khách sạn Ibiza Riverfront, GIC Luxury Hotel Đà Nẵng, khu nghỉ dưỡng Pullman Đà Nẵng Beach,...</p><p class=\"ql-align-justify\"><a href=\"https://media.vietravel.com/images/NewsPicture/du-xuan-ngay-tet-12.jpg\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 51, 51);\"><img src=\"https://media.vietravel.com/images/NewsPicture/du-xuan-ngay-tet-12.jpg\"><img src=\"https://www.vietravel.com/content/img/icon_zoom.png\" alt=\"Slideshow\"></a></p><p class=\"ql-align-center\">Khách sạn Ibiza Riverfront với tầm nhìn tuyệt đẹp</p><p><br></p>','Da Nang','Đà Nẵng','https://res.cloudinary.com/dbammk7wt/image/upload/v1722849640/j7atcr0gg4ajyihw6foz.webp','Da Nang'),(0,'2024-08-05 16:25:43.437023',4,'2024-08-05 16:25:43.437023',1,'admin','<h2><strong>Đảo Ngọc Vũng Tàu (Cù Lao Bãi Ngựa)</strong></h2><p><a href=\"https://www.klook.com/vi/city/549-vung-tau-things-to-do/?from_campaign=vn_dia-diem-du-lich-vung-tau_ao_vi-vn&amp;from_medium=content&amp;from_source=blog\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(32, 115, 249); background-color: rgb(255, 255, 255);\"><img src=\"https://res.klook.com/image/upload/fl_lossy.progressive,q_85/c_fill,w_1000/v1637737797/blog/orxssx5vqs4wajskbloj.webp\" alt=\"Đảo Ngọc (Cù Lao Bãi Ngựa)\"></a></p><p>Ấn tượng đầu tiên về Đảo Ngọc - hay còn có tên Cù Lao Bãi Ngựa - là cấu trúc tự nhiên vừa độc đáo vừa bắt mắt. Địa điểm này được tạo nên bởi những cây vẹt, cây đước lâu năm, đan tán vào nhau tạo thành một “thành luỹ” thuần xanh, có công dụng ngăn nước biển và tạo nên đường đi bộ. Khám phá phía bên trong Đảo Ngọc, #teamKlook sẽ được dịp trầm trồ trước hồ nước mặn trong vắt, lặng yên như tờ, cực kỳ phù hợp với các hoạt động thể chất như chèo thuyền Kayak, câu cá hoặc đi xe đạp nước. Đảo Ngọc ở Vũng Tàu là địa điểm du lịch trên-cả-tuyệt-vời dành cho gia đình có trẻ nhỏ hoặc nhóm du lịch tập thể, nhóm bạn, công ty</p>','Vung Tau','Vũng Tàu','https://res.cloudinary.com/dbammk7wt/image/upload/v1722849941/xcbbj4ob4xskyqlfgo8u.webp','Vung Tau'),(0,'2024-08-05 17:34:47.444632',5,'2024-08-05 17:34:47.444632',2,'staff','<p>Tour du lịch Quy Nhơn – Kỳ Co – Eo Gió – Cù Lao Xanh – Hòn Khô – Ghềnh Ráng – Phú Yên. Khởi hành liên tục trong ngày, đón và trả tại khách sạn với cam kết chất lượng nhất tại Quy Nhơn</p><h4><span style=\"color: rgb(255, 0, 0);\">Tour Kỳ Co – Eo Gió – Lặn Biển – Đồi Cát – Tượng Hai Thân</span></h4><p><a href=\"https://gotour.com.vn/bai-bien-ky-co-tai-quy-nhon-binh-dinh/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 255);\">Kỳ Co</a>&nbsp;là tour du lịch biển nổi bật nhất trong ngày tại Quy Nhơn, khởi hành mỗi ngày có xe đón tại khách sạn, bao tất cả mọi chi phí tham quan cho du khách với cam kết chất lượng và uy tín tại Quy Nhơn. Quý khách đi xong tour mới thanh toán nhé</p><h4><span style=\"color: rgb(255, 0, 0);\">Tour Quy Nhơn – Phú Yên trong ngày: Gành Đá Đĩa – Hoa Vàng Trên Cỏ Xanh</span></h4><p>Tour du lịch Quy Nhơn –&nbsp;<a href=\"https://vi.wikipedia.org/wiki/Ph%C3%BA_Y%C3%AAn\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 255);\">Phú Yên</a>&nbsp;trong ngày cũng là tour nổi bật, với các thắng cảnh đẹp tại Phú Yên như: Nhà Thờ Mằng Lăng, Gành Đá Đĩa, Đầm Ô Loan, Gành Ông Bãi Xép, Cầu Ông Cọp, Chùa Thanh Lương và đặc biệt bữa hải sản phong phú tại Phú Yên</p><h4><span style=\"color: rgb(255, 0, 0);\">City Tour Quy Nhơn</span></h4><p>Đây là tour rẻ nhất tại&nbsp;<a href=\"https://vi.wikipedia.org/wiki/Quy_Nh%C6%A1n\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 255);\">Quy Nhơn</a>&nbsp;hiện nay, chỉ với 250k bạn có thể tham quan Ghềnh Ráng, Mộ Hàn Mạc Tử, Dốc Mộng Cầm, Đồi Thi Nhân, Bãi Tắm Hoàng Hậu, Chùa Long Khánh, Tháp Đôi. Bạn chỉ cần 4 tiếng để dạo chơi gần hết thành phố xinh đẹp này nhé nhé</p><h4><span style=\"color: rgb(255, 0, 0);\">Tour Tây Sơn – Khu Du Lịch Hầm Hô</span></h4><p>Đây là tour du lịch Sinh Thái và về nguồn. Thăm bảo bàng Vua Quang Trung tại Tây Sơn, tìm hiểu về thân thế và sự nghiệp ba anh em nhà Tây Sơn. Cùng xem show nhạc võ đặc sắc nhất ở&nbsp;<a href=\"https://en.wikipedia.org/wiki/Vietnam\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 255);\">Việt Nam</a></p>','Binh Dinh','Bình Định','https://res.cloudinary.com/dbammk7wt/image/upload/v1722854085/swshbdfh5pcveekyfqvf.webp','Tour Quy Nhơn'),(0,'2024-08-07 14:27:31.726986',6,'2024-08-07 14:27:31.726986',2,'staff','<p class=\"ql-align-justify\">Không chỉ được thiên nhiên ban tặng cho những danh lam thắng cảnh hùng vĩ và hữu tình:&nbsp;<a href=\"https://www.tourismdanang.vn/diem-du-lich/ngu-hanh-son/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\">Ngũ Hành Sơn</a>,&nbsp;<a href=\"https://www.tourismdanang.vn/diem-du-lich/chua-linh-ung-tu/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\">Chùa Linh Ứng</a>,&nbsp;<a href=\"https://www.tourismdanang.vn/diem-du-lich/ba-na-hills/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\">Bà Nà Hills</a>… Đà Nẵng&nbsp;còn nổi tiếng với hàng loạt những cây cầu hiện đại bắc qua dòng sông Hàn thơ mộng:&nbsp;<a href=\"https://www.tourismdanang.vn/diem-du-lich/cau-song-han/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\">Cầu sông Hàn</a>, cầu Trần Thị Lý, cầu Thuận Phước, cầu Nguyễn Văn Trỗi…và đặc biệt là&nbsp;<strong>cầu Rồng</strong>&nbsp;– Cây cầu mới, độc đáo và hiện đại bậc nhất tại Đà Nẵng hiện nay . Chính vì lẽ đó mà&nbsp;<a href=\"https://www.tourismdanang.vn/gioi-thieu-da-nang/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\">Đà Nẵng</a>&nbsp;được nhân dân cả nước và bạn bè quốc tế ưu ái gọi bằng cái tên “Thành phố của những cây cầu”.</p><p class=\"ql-align-center\"><a href=\"https://www.tourismdanang.vn/wp-content/uploads/Cau-Rong-Da-Nang2.jpg\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\"><img src=\"https://www.tourismdanang.vn/wp-content/uploads/Cau-Rong-Da-Nang2.jpg\" alt=\"Cau Rong Da Nang\" height=\"416\" width=\"650\"></a></p><p class=\"ql-align-justify\"><strong>Cầu Rồng</strong>&nbsp;được khởi công xây dựng từ 19/7/2009 với tổng kinh phí đầu tư lên đến 1.500 tỷ đồng, cầu Rồng có tổng chiều dài 666 mét, rộng 37,5 mét, với 6 làn xe chạy, và chính thức được thông xe vào ngày 29/3/2013. Đây là cây cầu có kiến trúc độc đáo được Tập đoàn Louis Berger (Mỹ) thiết kế. Cây cầu hiện đại này bắc qua sông Hàn tạo thành con dường ngắn nhất nối liền sân bay quốc tế Đà Nẵng với các khu du lịch cao cấp ven biển đóng vai trò quan trọng trong chiến lược phát triển và hoàn thiện hạ tầng giao thông đô thị thành phố. Với thiết kế độc đáo, sáng tạo, bắt mắt mô phỏng hình dáng con rồng thời Lý đang uốn lượn trên dòng sông Hàn, đầu rồng ngẩng cao, hướng ra biển Đông, thân rồng thì uốn lượn, cầu Rồng nhanh chóng trở thành biểu tượng mới của thành phố Đà Nẵng.</p><p class=\"ql-align-center\"><a href=\"https://www.tourismdanang.vn/wp-content/uploads/Cau-Rong-Phun-Lua.jpg\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\"><img src=\"https://www.tourismdanang.vn/wp-content/uploads/Cau-Rong-Phun-Lua.jpg\" alt=\"Cau Rong Phun Lua\" height=\"431\" width=\"650\"></a></p><p class=\"ql-align-justify\">Đặc biệt vào mỗi tối thứ 7, chủ nhật và các ngày lễ lớn, lúc 21h00 Cầu rồng sẽ trình diễn màn phun lửa, phun nước bằng công nghệ hiện đại kết hợp với hệ thống đèn chiếu sáng trên cầu, tất cả tạo thành một con đường lung linh, huyền ảo, rực rỡ sắc màu.</p><p class=\"ql-align-center\"><a href=\"https://www.tourismdanang.vn/wp-content/uploads/Cau-Rong.jpg\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(51, 102, 204);\"><img src=\"https://www.tourismdanang.vn/wp-content/uploads/Cau-Rong.jpg\" alt=\"Cau Rong\" height=\"431\" width=\"650\"></a></p><p class=\"ql-align-justify\">Với phong cách thiết kế hiện đại cùng với khả năng phun lửa, phun nước, cầu Rồng nằm trong danh sách 30 cây cầu ấn tượng nhất thế giới; và được báo chí Mỹ hết lời ca ngợi và cho rằng đây là “Biểu tượng cho sự thịnh vượng” của Châu Á.</p>','Cau Rong ','Đà Nẵng','https://res.cloudinary.com/dbammk7wt/image/upload/v1723015649/pphqs5ssoyozn1zjm3ds.jpg','Da Nang'),(1,'2024-08-07 14:29:17.172941',7,'2024-08-09 01:01:41.200388',2,'staff','<p>tét</p>','tét','Đà Nẵng','https://res.cloudinary.com/dbammk7wt/image/upload/v1723015755/bmcyafe69qx0olxwmngj.jpg','tet');
